// GmPlug, GmLinkedListNode, GmLinkedList, GmLinkedListIterator — recovered methods.
// One file because the original functions are contiguous at 0x00076C10-0x000770FE and vftables are adjacent.
// Verification status per function: config/functions.toml, docs/PROGRESS.md (generated by tools/verify.py).
#include "gm/GmLinkedList.h"

GmPlug::GmPlug() {
    m_connections = 0;
}

GmPlug::~GmPlug() {
    GmConnection* c = m_connections;
    while (c) {
        GmConnection* next = c->m_plugNext;
        c->Disconnect();
        c = next;
    }
    m_connections = 0;
}

void GmPlug::DisconnectAll() {
    GmConnection* c = m_connections;
    while (c) {
        GmConnection* next = c->m_plugNext;
        c->Disconnect();
        c = next;
    }
    m_connections = 0;
}

void GmPlug::Disconnect(GmSocket* socket) {
    for (GmConnection* c = m_connections; c; c = c->m_plugNext) {
        if (c->m_socket == socket) {
            c->Disconnect();
            return;
        }
    }
}

int GmPlug::IsConnectedTo(GmSocket* socket) {
    for (GmConnection* c = m_connections; c; c = c->m_plugNext) {
        if (c->m_socket == socket) {
            return 1;
        }
    }
    return 0;
}

int GmLinkedListNode::s_cursor;                                          // 0x002E26E8
GmLinkedListNode GmLinkedListNode::s_pool[GmLinkedListNode::kPoolSize];  // 0x002E26F0

GmLinkedListNode::GmLinkedListNode() {
    m_active = 0;
}

GmLinkedListNode::~GmLinkedListNode() {
    GmLinkedListNode::Disconnect();
}

void GmLinkedListNode::Disconnect() {
    if (!m_active) {
        return;
    }
    GmLinkedList* list = static_cast<GmLinkedList*>(m_socket);
    if (prev) {
        prev->next = next;
    } else {
        list->head = next;
    }
    if (next) {
        next->prev = prev;
    } else {
        list->tail = prev;
    }
    next = 0;
    prev = 0;
    m_active = 0;
    Unlink();
}

GmLinkedListNode* GmLinkedListNode::Allocate() {
    int index = s_cursor;
    for (int tried = 0; tried < kPoolSize; tried++) {
        if (!s_pool[index].m_active) {
            s_cursor = index;
            s_pool[index].m_active = 1;
            return &s_pool[index];
        }
        index++;
        if (index == kPoolSize) {
            index = 0;
        }
    }
    s_cursor = index;
    return 0;
}

GmLinkedList::GmLinkedList() : GmSocket(0) {
    head = 0;
    tail = 0;
}

GmLinkedList::~GmLinkedList() {
    SetContext(0);
    GmLinkedListNode* node = head;
    while (node) {
        GmLinkedListNode* following = node->next;
        node->Disconnect();
        node = following;
    }
}

void GmLinkedList::Append(GmPlug* item) {
    GmLinkedListNode* node = GmLinkedListNode::Allocate();
    GmLinkedListNode* last = tail;
    node->Connect(this, item);
    node->next = 0;
    node->prev = last;
    if (last) {
        last->next = node;
    }
    node->m_active = 1;
    tail = node;
    if (!head) {
        head = node;
    }
}

int GmLinkedList::IsEmpty() {
    return head == 0;
}

GmLinkedListIterator::GmLinkedListIterator(GmLinkedList* list) : GmSocketIterator(list) {
    if (list) {
        m_cur = list->head;
    }
}

void GmLinkedListIterator::First() {
    m_cur = List()->head;
}

void GmLinkedListIterator::Last() {
    m_cur = List()->tail;
}

void GmLinkedListIterator::Next() {
    if (m_cur) {
        m_cur = m_cur->next;
    }
}

// Original behaviour preserved: unlike Next(), m_cur itself is not null-checked here.
void GmLinkedListIterator::Prev() {
    GmLinkedListNode* prev = m_cur->prev;
    if (prev) {
        m_cur = prev;
    }
}

void* GmLinkedListIterator::NextData() {
    GmLinkedListNode* node = m_cur;
    if (!node) {
        return 0;
    }
    void* data = node->m_plug;
    m_cur = node->next;
    return data;
}

void* GmLinkedListIterator::PrevData() {
    GmLinkedListNode* node = m_cur;
    if (!node) {
        return 0;
    }
    void* data = node->m_plug;
    m_cur = node->prev;
    return data;
}

void* GmLinkedListIterator::Current() {
    if (!m_cur) {
        return 0;
    }
    return m_cur->m_plug;
}

// Original behaviour preserved: First() is a virtual call; an empty list with index <= 0 dereferences null.
void* GmLinkedListIterator::At(int index) {
    First();
    for (int i = 0; i < index; i++) {
        GmLinkedListNode* next = m_cur->next;
        if (!next) {
            return 0;
        }
        m_cur = next;
    }
    return m_cur->m_plug;
}

int GmLinkedListIterator::Count() {
    GmLinkedList* list = List();
    int count = 0;
    if (list) {
        for (GmLinkedListNode* node = list->head; node; node = node->next) {
            count++;
        }
    }
    return count;
}

void GmLinkedListIterator::RemoveCurrent() {
    GmLinkedListNode* node = m_cur;
    if (node) {
        GmLinkedListNode* following = node->next;
        node->Disconnect();
        m_cur = following;
    }
}

void GmLinkedListIterator::RemoveAll() {
    for (;;) {
        First();
        if (!Current()) {
            return;
        }
        RemoveCurrent();
    }
}
